def import_daily_notes(apps, schema_editor):
    """Make saved short notes findable without rewriting or rewarding them."""
    Entry = apps.get_model("chronicle", "ChronicleEntry")
    Wellbeing = apps.get_model("wellbeing", "DailyWellbeingEntry")
    database = schema_editor.connection.alias
    for source in Wellbeing.objects.using(database).iterator(chunk_size=500):
        if not isinstance(source.gratitude_lines, list):
            continue
        lines = [line for line in source.gratitude_lines if isinstance(line, str) and line.strip()]
        if not lines:
            continue
        entry, created = Entry.objects.using(database).get_or_create(
            daily_note_source_id=source.pk,
            defaults={
                "user_id": source.user_id,
                "kind": "daily_note",
                "occurred_on": source.date,
                "chapter_year": source.date.year if source.date.month >= 8 else source.date.year - 1,
                "title": "Daily note",
                "summary": "\n\n".join(lines),
                "is_private": True,
                "metadata": {"reward_receipt": {
                    "status": "unavailable", "xp_awarded": 0, "skills": [],
                    "coins_awarded": 0, "coin_status": "unavailable",
                }},
            },
        )
        if created:
            Entry.objects.using(database).filter(pk=entry.pk).update(created_at=source.created_at)


